manialink.script:
#RequireContext CMlBrowser

if (CurMap == Null) {
	return;
}
declare Integer CampaignOffset;
switch (LoadedTitle.TitleId) {
	case "TMCanyon@nadeo": {
		CampaignOffset = 0;
	}
	case "TMStadium@nadeo": {
		CampaignOffset = 65;
	}
	case "TMValley@nadeo": {
		CampaignOffset = 130;
	}
	case "TMLagoon@nadeo": {
		CampaignOffset = 195;
	}
	default: {
		CampaignOffset = -1;
	}
}
if (CampaignOffset == -1) {
	return;
}
declare MapFound = False;
declare MapNum = 0;
foreach (Campaign in DataFileMgr.Campaigns) {
	foreach (MapGroup in Campaign.MapGroups) {
		foreach (MapInfo in MapGroup.MapInfos) {
			MapNum += 1;
			if (MapInfo.MapUid == CurMap.MapInfo.MapUid) {
				MapFound = True;
				break;
			}
		}
		if (MapFound) {
			break;
		}
	}
	if (MapFound) {
		break;
	}
}
if (!MapFound) {
	return;
}
log("#campaign=#(" ^ CampaignOffset ^ " + " ^ MapNum ^ ")@Nadeo_Envimix@bigbang1112");
OpenLink("#campaign=#" ^ CampaignOffset + MapNum ^ "@Nadeo_Envimix@bigbang1112", CMlScript::LinkType::ManialinkBrowser);
